import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0519_2/projects/cert_manip_resist_eval/docs/paper/data/cross_benchmark_iv.json') as f:
    data = json.load(f)

# exclusion restriction
ert = data.get('exclusion_restriction_test', {})
for k in ['K3', 'K5', 'K7']:
    if k in ert:
        print(f'{k} exclusion r={ert[k].get(\"r_keff_mmlu_keff_arc\", \"?\"):.4f}')

# reduced form summary
rf = data.get('reduced_form', {})
for k in ['K3', 'K5', 'K7']:
    if k in rf:
        for d in rf[k]:
            if '_summary' in rf[k][d]:
                s = rf[k][d]['_summary']
                print(f'  {k} {d}: keff={s.get(\"keff_sig\",\"?\")}, eta={s.get(\"eta_sig\",\"?\")}')

# 2SLS
ts = data.get('two_sls', {})
for k in ['K3', 'K5', 'K7']:
    if k in ts:
        n_strong = sum(1 for v in ts[k].values() if isinstance(v, dict) and v.get('strong_instrument'))
        print(f'  {k} 2SLS strong: {n_strong}/6')

print()
print(data.get('summary_from_server', ''))
